package com.aevum.bounties;
import org.bukkit.Bukkit;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.player.AsyncPlayerChatEvent;import java.util.*;
public final class ChatFlow implements Listener{
 private static final Set<UUID>T=new HashSet<>(),A=new HashSet<>();private final AevumBounties p;private final BountyManager m;private final Player pl;private String target;
 public ChatFlow(AevumBounties p,BountyManager m,BountyGUI g,Player pl){this.p=p;this.m=m;this.pl=pl;}
 public void start(){T.add(pl.getUniqueId());Bukkit.getPluginManager().registerEvents(this,p);pl.sendMessage(AevumBounties.color("&6&lBOUNTY &8» &7Enter target username. &8(&ccancel&8)")); }
 @EventHandler public void chat(AsyncPlayerChatEvent e){if(!e.getPlayer().equals(pl))return;UUID id=pl.getUniqueId();if(!T.contains(id)&&!A.contains(id))return;e.setCancelled(true);String s=e.getMessage().trim();if(s.equalsIgnoreCase("cancel")){done();return;}if(T.remove(id)){Player x=Bukkit.getPlayerExact(s);if(x==null){T.add(id);pl.sendMessage(AevumBounties.color("&cPlayer is not online."));return;}if(!p.getConfig().getBoolean("settings.allow-self",false)&&x.equals(pl)){T.add(id);pl.sendMessage(AevumBounties.color("&cYou cannot bounty yourself."));return;}target=x.getName();A.add(id);pl.sendMessage(AevumBounties.color("&6&lBOUNTY &8» &7Enter reward amount."));return;}if(A.remove(id)){double amount;try{amount=Double.parseDouble(s);}catch(Exception ex){A.add(id);pl.sendMessage(AevumBounties.color("&cInvalid amount."));return;}double min=p.getConfig().getDouble("settings.min-bounty"),max=p.getConfig().getDouble("settings.max-bounty");if(!Double.isFinite(amount)||amount<min||amount>max){A.add(id);pl.sendMessage(AevumBounties.color("&cAmount must be between &6"+p.money(min)+" &cand &6"+p.money(max)+"&c."));return;}Player x=Bukkit.getPlayerExact(target);if(x==null){done();pl.sendMessage(AevumBounties.color("&cTarget went offline."));return;}Bounty b=m.create(pl,x,amount);if(b==null){done();pl.sendMessage(AevumBounties.color("&cNot enough money or safe save failed."));return;}pl.sendMessage(AevumBounties.color("&a✓ Bounty placed on &e"+target+" &afor &6"+p.money(amount)+"&a."));if(p.getConfig().getBoolean("settings.announce-new-bounties",true))p.announce("&6☠ &e"+pl.getName()+" &7placed a &6"+p.money(amount)+" &7bounty on &c"+target+"&7.");done();}}
 private void done(){UUID id=pl.getUniqueId();T.remove(id);A.remove(id);HandlerList.unregisterAll(this);}
}